import React, { useState } from "react";
import { useNavigate, Navigate } from "react-router-dom";
import { useCart } from "../context/CartContext";
import api from "../api/api";

const Checkout = () => {
  const { items, subtotal, clearCart } = useCart();
  const navigate = useNavigate();

  const [form, setForm] = useState({
    fullName: "",
    phone: "",
    address: "",
    city: "",
    email: "",
    notes: "",
  });
  const [paymentMethod, setPaymentMethod] = useState("COD");
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState("");

  if (items.length === 0) {
    return <Navigate to="/cart" replace />;
  }

  const shippingFee = subtotal >= 5000 ? 0 : 250;
  const total = subtotal + shippingFee;

  const handleChange = (e) => setForm({ ...form, [e.target.name]: e.target.value });

  const handleSubmit = async (e) => {
    e.preventDefault();
    setSubmitting(true);
    setError("");

    try {
      const orderPayload = {
        items: items.map((i) => ({
          product: i.productId,
          name: i.name,
          size: i.size,
          color: i.color,
          quantity: i.quantity,
        })),
        customer: form,
        paymentMethod,
      };

      const { data } = await api.post("/orders", orderPayload);
      clearCart();
      navigate(`/order-confirmation/${data._id}`);
    } catch (err) {
      setError(err.response?.data?.message || "Failed to place order. Please try again.");
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div className="max-w-5xl mx-auto px-5 py-16 grid md:grid-cols-3 gap-10">
      <form onSubmit={handleSubmit} className="md:col-span-2 flex flex-col gap-5">
        <h1 className="text-3xl text-ivory mb-4">Checkout</h1>

        {error && <p className="text-maroon text-sm">{error}</p>}

        <div>
          <label className="text-sm text-ivory block mb-1">Full Name</label>
          <input
            required
            name="fullName"
            value={form.fullName}
            onChange={handleChange}
            className="w-full bg-charcoal border border-brass/20 text-ivory px-4 py-3 text-sm focus:border-brass outline-none"
          />
        </div>

        <div className="grid grid-cols-2 gap-4">
          <div>
            <label className="text-sm text-ivory block mb-1">Phone</label>
            <input
              required
              name="phone"
              value={form.phone}
              onChange={handleChange}
              className="w-full bg-charcoal border border-brass/20 text-ivory px-4 py-3 text-sm focus:border-brass outline-none"
            />
          </div>
          <div>
            <label className="text-sm text-ivory block mb-1">Email (optional)</label>
            <input
              name="email"
              type="email"
              value={form.email}
              onChange={handleChange}
              className="w-full bg-charcoal border border-brass/20 text-ivory px-4 py-3 text-sm focus:border-brass outline-none"
            />
          </div>
        </div>

        <div>
          <label className="text-sm text-ivory block mb-1">Address</label>
          <input
            required
            name="address"
            value={form.address}
            onChange={handleChange}
            className="w-full bg-charcoal border border-brass/20 text-ivory px-4 py-3 text-sm focus:border-brass outline-none"
          />
        </div>

        <div>
          <label className="text-sm text-ivory block mb-1">City</label>
          <input
            required
            name="city"
            value={form.city}
            onChange={handleChange}
            className="w-full bg-charcoal border border-brass/20 text-ivory px-4 py-3 text-sm focus:border-brass outline-none"
          />
        </div>

        <div>
          <label className="text-sm text-ivory block mb-1">Order Notes (optional)</label>
          <textarea
            name="notes"
            value={form.notes}
            onChange={handleChange}
            rows={3}
            className="w-full bg-charcoal border border-brass/20 text-ivory px-4 py-3 text-sm focus:border-brass outline-none"
          />
        </div>

        <div>
          <p className="text-sm text-ivory mb-2">Payment Method</p>
          <div className="flex gap-4">
            <button
              type="button"
              onClick={() => setPaymentMethod("COD")}
              className={`px-5 py-3 border text-sm ${
                paymentMethod === "COD" ? "border-brass text-brass" : "border-brass/20 text-stone"
              }`}
            >
              Cash on Delivery
            </button>
            <button
              type="button"
              onClick={() => setPaymentMethod("Online")}
              className={`px-5 py-3 border text-sm ${
                paymentMethod === "Online" ? "border-brass text-brass" : "border-brass/20 text-stone"
              }`}
            >
              Online Payment
            </button>
          </div>
        </div>

        <button
          type="submit"
          disabled={submitting}
          className="bg-brass text-ink py-3 text-sm mt-4 hover:bg-ivory transition-colors disabled:opacity-50"
        >
          {submitting ? "Placing Order..." : "Place Order"}
        </button>
      </form>

      <div className="bg-charcoal border border-brass/10 p-6 h-fit">
        <h2 className="text-ivory text-lg mb-5">Order Summary</h2>
        <div className="flex flex-col gap-3 mb-5">
          {items.map((item) => (
            <div key={`${item.productId}-${item.size}-${item.color}`} className="flex justify-between text-sm">
              <span className="text-stone">
                {item.name} &times; {item.quantity}
              </span>
              <span className="text-ivory">Rs. {(item.price * item.quantity).toLocaleString()}</span>
            </div>
          ))}
        </div>
        <div className="stitch-divider mb-4" />
        <div className="flex justify-between text-sm text-stone mb-2">
          <span>Subtotal</span>
          <span>Rs. {subtotal.toLocaleString()}</span>
        </div>
        <div className="flex justify-between text-sm text-stone mb-4">
          <span>Shipping</span>
          <span>{shippingFee === 0 ? "Free" : `Rs. ${shippingFee}`}</span>
        </div>
        <div className="flex justify-between text-ivory">
          <span>Total</span>
          <span>Rs. {total.toLocaleString()}</span>
        </div>
      </div>
    </div>
  );
};

export default Checkout;
